(3612876, 505782, 31307, '<td valign="top">I think this image has "the makings" bu I would like to see the tonal ranges of the waves pushed further into the shadow range.  They seem a little to light to me.  From looking at the remains of the pier, that may not have been possible to do within the rules and still keep the piers from clipping at the bottom range of the tonal spectrum, which is unfortunate.</td>', 'I think this image has "the makings" bu I would like to see the tonal ranges of the waves pushed further into the shadow range.  They seem a little to light to me.  From looking at the remains of the pier, that may not have been possible to do within the rules and still keep the piers from clipping at the bottom range of the tonal spectrum, which is unfortunate.', '2007-05-03 23:45:19.000000', NULL, 1),
(3612877, 503964, 31307, '<td valign="top">Heh.  Clever title.</td>', 'Heh.  Clever title.', '2007-05-03 23:45:56.000000', NULL, 1),
