INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3627399, 504337, 74371, '<td valign="top">Sorry... out of focus, exposure settings off, and as far as I can see... no relationship to Pi. I think you could have done a good deal better. <br/> <br/>Interesting shot though and I can understand why you wanted to enter it somewhere.</td>', 'Sorry... out of focus, exposure settings off, and as far as I can see... no relationship to Pi. I think you could have done a good deal better.  Interesting shot though and I can understand why you wanted to enter it somewhere.', '2007-05-08 02:21:00.000000', NULL, 1),
(3627403, 506107, 74371, '<td valign="top">I would love to know how you did this using basic editing. Good shot! (6)</td>', 'I would love to know how you did this using basic editing. Good shot! (6)', '2007-05-08 02:22:34.000000', NULL, 1),
(3627601, 506152, 59905, '<td valign="top">Great shot, great lighting! The negative space definitely adds to the feeling of the texture and detail on the rocks. There''s just enough in there to not get it boring, and I love the image for it! 9</td>', 'Great shot, great lighting! The negative space definitely adds to the feeling of the texture and detail on the rocks. There''s just enough in there to not get it boring, and I love the image for it! 9', '2007-05-08 05:26:22.000000', NULL, 1),
(3627603, 506010, 59905, '<td valign="top">This photo gives me too much of a snapshot feeling, mostly due to the point of view (rather high up, looking down). I think this image would benefit from a very high point of view, maybe stand on a ladder and shoot it almost straight down. <br/>Also, an interesting object in the pan would make it more interesting. (Maybe even light the fire? It should make a cool sight from above)</td>', 'This photo gives me too much of a snapshot feeling, mostly due to the point of view (rather high up, looking down). I think this image would benefit from a very high point of view, maybe stand on a ladder and shoot it almost straight down. Also, an interesting object in the pan would make it more interesting. (Maybe even light the fire? It should make a cool sight from above)', '2007-05-08 05:30:05.000000', NULL, 1),
(3627973, 505499, 20494, '<td valign="top">Wow! spectacular shot....would really like to know how''s it''s done!</td>', 'Wow! spectacular shot....would really like to know how''s it''s done!', '2007-05-08 10:13:55.000000', NULL, 1),
(3627988, 506107, 20494, '<td valign="top">impressive shot</td>', 'impressive shot', '2007-05-08 10:21:41.000000', NULL, 1),
(3628584, 503223, 58452, '<td valign="top">I love the repeating pattern of lines, rectangles, and squares, all surrounded by a circle. The pi itself could stand out more, but this is my pick for the blue!</td>', 'I love the repeating pattern of lines, rectangles, and squares, all surrounded by a circle. The pi itself could stand out more, but this is my pick for the blue!', '2007-05-08 13:05:57.000000', NULL, 1),
